"""Build the calculator entry point after editing either frontend source."""
from pathlib import Path

root = Path(__file__).resolve().parents[1]
static = root / "static"
(static / "calculator-20261029.js").write_text(
    "// Generated by scripts/build_frontend.py; edit i18n.js and app.js, then rebuild.\n"
    + (static / "i18n.js").read_text() + "\n;\n" + (static / "app.js").read_text(),
    encoding="utf-8",
)
